INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Schnittstellenbeschreibungen ohne Parameterangaben vollständig?', 2, '[{"text": "Nein", "correct": true, "because": "Parameter sind essenziell"}, {"text": "Ja", "correct": false, "because": "Fehlende Details"}]'),
