('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schnittstellenbeschreibungen brauchen Rückgabewerte. b) Sie sind nur für große Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch kleine Projekte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Schnittstellenbeschreibung?', 5, '[{"text": "Einfache Integration", "correct": true, "because": "Klarheit hilft"}, {"text": "Fehlerreduktion", "correct": true, "because": "Missverständnisse sinken"}, {"text": "Hohe Performance", "correct": false, "because": "Kein direkter Einfluss"}, {"text": "Schnelle Tests", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Schnittstellenbeschreibung unwichtig?', 3, '[{"text": "Parameter", "correct": false, "because": "Kern der Doku"}, {"text": "Rückgabewerte", "correct": false, "because": "Definiert Ausgabe"}, {"text": "Autorname", "correct": true, "because": "Nicht funktional"}]'),
